using DrawDecks.Domain;
using Xunit;
namespace DrawDecks.Domain.Tests;
public sealed class CardSystemTests {
 static readonly CardCatalog Catalog=CardCatalog.CreateDefault();
 static SeatDefinition[] Seats()=>new[]{new SeatDefinition("p1","Player 1",SeatKind.Human),new SeatDefinition("p2","Player 2",SeatKind.Cpu)};
 static MatchState Match(ulong seed=42)=>MatchFactory.Create("test-"+seed,seed,Seats(),Catalog);
 [Fact] public void CatalogIncludesAllRequestedEffects(){var effects=Catalog.Definitions.Select(x=>x.Effect).ToHashSet();foreach(var e in new[]{CardEffect.DrawTwo,CardEffect.SkipTurn,CardEffect.ReverseOrder,CardEffect.SwapHands,CardEffect.StealCard,CardEffect.DiscardRandomCard,CardEffect.BlockDraw,CardEffect.Shield,CardEffect.Reflect,CardEffect.Negate,CardEffect.Wild,CardEffect.DeckReset,CardEffect.DoubleScore})Assert.Contains(e,effects);Assert.Equal(52,Catalog.Definitions.Count(x=>x.Kind==CardKind.Standard));}
 [Fact] public void DeckShuffleIsDeterministicAndInstancesUnique(){var ids=Catalog.Definitions.Select(x=>x.Id).ToArray();var a=DeckBuilder.Create(Catalog,ids,77);var b=DeckBuilder.Create(Catalog,ids,77);Assert.Equal(a.Select(x=>x.DefinitionId),b.Select(x=>x.DefinitionId));Assert.Equal(a.Count,a.Select(x=>x.InstanceId).Distinct().Count());}
 [Fact] public void ValidationRejectsDuplicatesAndUnknownCards(){var result=DeckBuilder.Validate(Catalog,new[]{"action-skip","action-skip","bad"});Assert.False(result.IsValid);Assert.Equal(2,result.Errors.Count);}
 [Fact] public void DrawAndDiscardMoveCards(){var s=Match();var p=s.CurrentPlayer;int count=p.Hand.Count;Assert.True(GameEngine.Draw(s,p.Id).Success);Assert.Equal(count+1,p.Hand.Count);var id=p.Hand[0].InstanceId;Assert.True(GameEngine.Discard(s,p.Id,id).Success);Assert.Contains(s.DiscardPile,c=>c.InstanceId==id);}
 [Fact] public void HandLimitAndEmptyDeckAreEnforced(){var s=Match();Assert.True(GameEngine.Draw(s,s.CurrentPlayer.Id,2).Success);Assert.Equal(ActionError.HandLimitReached,GameEngine.Draw(s,s.CurrentPlayer.Id,1).Error);var tiny=MatchFactory.Create("tiny",9,Seats(),Catalog,new Ruleset(1,1),new[]{"standard-hearts-2","standard-hearts-3"});Assert.Equal(ActionError.DeckEmpty,GameEngine.Draw(tiny,tiny.CurrentPlayer.Id).Error);}
 [Fact] public void InvalidPlayDoesNotMutateHand(){var s=Match();int n=s.CurrentPlayer.Hand.Count;Assert.Equal(ActionError.CardNotInHand,GameEngine.PlayCard(s,s.CurrentPlayer.Id,"missing").Error);Assert.Equal(n,s.CurrentPlayer.Hand.Count);}
 [Fact] public void AttackCanBeNegatedAndEventsAreSequenced(){var s=Match();var a=s.CurrentPlayer;var d=s.Players[1];a.MutableHand.Add(new CardInstance("atk",Catalog.Get("attack-steal")));d.MutableHand.Add(new CardInstance("def",Catalog.Get("defense-negate")));Assert.True(GameEngine.PlayCard(s,a.Id,"atk",d.Id).Success);Assert.NotNull(s.PendingAttack);Assert.True(GameEngine.RespondToAttack(s,d.Id,"def").Success);Assert.Null(s.PendingAttack);Assert.Equal(s.Events.Count,s.Events.Select(e=>e.Sequence).Distinct().Count());}
 [Fact] public void DrawTwoResolvesInDomain(){var s=Match();var p=s.CurrentPlayer;p.MutableHand.Add(new CardInstance("draw2",Catalog.Get("action-draw-2")));int before=p.Hand.Count;Assert.True(GameEngine.PlayCard(s,p.Id,"draw2").Success);Assert.Equal(before+1,p.Hand.Count);}
 [Fact] public void ReverseAndSwapResolveInDomain(){var s=Match();var p=s.CurrentPlayer;var other=s.Players[1];p.MutableHand.Add(new CardInstance("rev",Catalog.Get("action-reverse")));Assert.True(GameEngine.PlayCard(s,p.Id,"rev").Success);Assert.Equal("p2",s.CurrentPlayer.Id);s.CurrentPlayer.MutableHand.Add(new CardInstance("swap",Catalog.Get("action-swap")));var old=s.CurrentPlayer.Hand.Where(c=>c.InstanceId!="swap").Select(c=>c.InstanceId).ToArray();var oldOther=p.Hand.Select(c=>c.InstanceId).ToArray();Assert.True(GameEngine.PlayCard(s,s.CurrentPlayer.Id,"swap",p.Id).Success);Assert.Equal(old,p.Hand.Select(c=>c.InstanceId));Assert.Equal(oldOther,s.CurrentPlayer.Hand.Select(c=>c.InstanceId));}
 [Fact] public void WildDoubleScoreAndDeckResetResolve(){var s=Match();var p=s.CurrentPlayer;p.MutableHand.Add(new CardInstance("wild",Catalog.Get("special-wild")));Assert.True(GameEngine.PlayCard(s,p.Id,"wild").Success);p.MutableHand.Add(new CardInstance("double",Catalog.Get("special-double")));Assert.True(GameEngine.PlayCard(s,p.Id,"double").Success);p.MutableHand.Add(new CardInstance("reset",Catalog.Get("special-reset")));Assert.True(GameEngine.PlayCard(s,p.Id,"reset").Success);}
}